#include <iostream>
#include <algorithm>

using namespace std;

using ll = long long;

ll mini(const ll a[], ll length)
{
    return *min_element(a, a + length);
}

int main()
{
    ll n, a, b, c;
    cin >> n >> a >> b >> c;

    ll k = (4 - n % 4) % 4;
    ll r[6];
    ll ans = 0;

    if (k == 3)
    {
        r[0] = c;
        r[1] = b + a;
        r[2] = 3 * a;
        r[3] = a + 2 * b;
        ans = mini(r, 4);
    }
    else if (k == 2)
    {
        r[0] = b;
        r[1] = 2 * a;
        r[2] = 2 * c;
        r[3] = 3 * b;
        ans = mini(r, 4);
    }
    else if (k == 1)
    {
        r[0] = a;
        r[1] = c + b;
        r[2] = 3 * c;
        r[3] = 3 * b + c;
        r[4] = 4 * c + a;
        r[5] = 6 * b + a;
        ans = mini(r, 6);
    }

    cout << ans << '\n';
    return 0;
}

